entries[43626] = { ["name"] = "Happy Pet Snack", ["text"] = "Binds when picked up\nUse: Feed your Companion Pet a snack.\nSell Price:" }
entries[43627] = { ["name"] = "Thrall's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Grom, may you rest well, old friend.\"\nSell Price:" }
entries[43628] = { ["name"] = "Lady Jaina Proudmoore's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Arthas, my love, please come back to me.\"\nSell Price:" }
entries[43629] = { ["name"] = "Uther Lightbringer's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Young Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.\"\nSell Price:" }
entries[43630] = { ["name"] = "Tirion Fordring's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"It is my wish that my dear Taelan will grow strong enough to defend the people he cares for.\"\nSell Price:" }
entries[43631] = { ["name"] = "Teron's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Wishes are a fool's pastime. Take this coin as payment for your precious Eye.\"\nSell Price:" }
entries[43632] = { ["name"] = "Sylvanas Windrunner's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"I hope my sisters and I can grow up and get married together. This coin appears to be very old.\"\nSell Price:" }
entries[43633] = { ["name"] = "Prince Kael'thas Sunstrider's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"That young apprentice Jaina is quite attractive for a human. I hope she recognizes my elegance and power.\"\nSell Price:" }
entries[43634] = { ["name"] = "Lady Katrana Prestor's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Listen, little wishing fountain. You'll give me all your power if you know what's good for you.\"\nSell Price:" }
entries[43635] = { ["name"] = "Kel'Thuzad's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Sometimes... I wish someone would come along and just give me a big, long hug.\"\nSell Price:" }
entries[43636] = { ["name"] = "Chromie's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Just once, I wish someone would greet me without making a stupid joke about gnomes or time travel.\"\nSell Price:" }
entries[43637] = { ["name"] = "Brann Bronzebeard's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Brann Bronzebeard was here.\"\nSell Price:" }
entries[43638] = { ["name"] = "Arugal's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"I wish someday to retire to my own tidy little estate, with a bunch of pet dogs to keep me company.\"\nSell Price:" }
entries[43639] = { ["name"] = "Arthas' Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Already, I've a kingdom in my prospects, a land to rule. What to ask for? Perhaps a frozen scone...\"\nSell Price:" }
entries[43640] = { ["name"] = "Archimonde's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"I wish to know how you survived my wrath, little fountain.\"\nSell Price:" }
entries[43641] = { ["name"] = "Anduin Wrynn's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"I wish I would grow up, it feels like I've been 10 for years.\"\nSell Price:" }
entries[43643] = { ["name"] = "Prince Magni Bronzebeard's Silver Coin", ["text"] = "\"I hope that my father and brothers outlive me. I'll not make much of a king.\"\nSell Price:" }
entries[43644] = { ["name"] = "A Peasant's Silver Coin", ["text"] = "\"I'm so forgetful! I wish I had a better memory. Wait, didn't I already throw a coin into here?\"\nSell Price:" }
entries[43645] = { ["name"] = "Bent Fishing Hook", ["text"] = "\"Looks like someone tried to fish in this fountain. Who would do such a thing?\"\nSell Price:" }
entries[43646] = { ["name"] = "Fountain Goldfish", ["text"] = "Requires Level 65\nUse: Restores 7498 health over 30 sec. Must remain seated while eating.\nSell Price:" }
entries[43647] = { ["name"] = "Shimmering Minnow", ["text"] = "Requires Level 70\nUse: Restores 18479 health over 30 sec. Must remain seated while eating.\nSell Price:" }
entries[43650] = { ["name"] = "Rusty Prison Key", ["text"] = "Binds when picked up\n\"Resembles a key used to open underwater treasure chests...\"\nSell Price:" }
entries[43651] = { ["name"] = "Crafty's Pole", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Fishing Pole 722 - 1,084 Damage Speed 3.00\n(301.00 damage per second)\nDurability 95 / 95\nRequires Fishing (1)\nEquip: Fishing skill increased by 1000.\n\"Just holding this fishing pole makes you shiver with excitement. This is possibly the most amazing thing you've ever seen.\"\nSell Price:" }
entries[43652] = { ["name"] = "Slippery Eel", ["text"] = "Requires Level 70\nUse: Restores 18479 health over 30 sec. If you spend at least 10 seconds eating you will become well fed and gain 40 dodge for 1 hour.\nSell Price:" }
entries[43653] = { ["name"] = "Partially Eaten Fish", ["text"] = "\"Small tooth marks can be seen on the carcass.\"\nSell Price:" }
entries[43654] = { ["name"] = "Tome of the Dawn", ["text"] = "Binds when equipped\nHeld In Off-hand\n+9 Stamina\n+5 Intellect\nRequires Level 20\nSell Price:" }
entries[43655] = { ["name"] = "Book of Survival", ["text"] = "Binds when equipped\nHeld In Off-hand\n+7 Stamina\nRequires Level 20\nEquip: Restores 7 health per 5 sec.\nSell Price:" }
entries[43656] = { ["name"] = "Tome of Kings", ["text"] = "Binds when equipped\nHeld In Off-hand\n+6 Stamina\n+ 5 Hit\n+ 6 Critical Strike\nRequires Level 30\nUse: Increases your stats by 14 for 1 min. (10 Min Cooldown)\nSell Price:" }
entries[43657] = { ["name"] = "Royal Guide of Escape Routes", ["text"] = "Binds when equipped\nHeld In Off-hand\n+ 11 Haste\nRequires Level 30\nUse: Heal you for 405 . (5 Min Cooldown)\nSell Price:" }
entries[43658] = { ["name"] = "Partially Rusted File", ["text"] = "\"The file has a slight green tinge to it.\"\nSell Price:" }
entries[43659] = { ["name"] = "Bloodied Prison Shank", ["text"] = "One-Hand Dagger\n124 - 230 Damage Speed 2.00\n(88.50 damage per second)\nDurability 55 / 55\nRequires Level 70\n\"The business end of this shank looks like profits were high this year.\"\nSell Price:" }
entries[43660] = { ["name"] = "Fire Eater's Guide", ["text"] = "Binds when equipped\nHeld In Off-hand\n+10 Intellect\n+ 9 Critical Strike\nRequires Level 40\nUse: Breathe fire on enemies in front of you, dealing 392 Fire damage. (2 Min Cooldown)\nSell Price:" }
entries[43661] = { ["name"] = "Book of Stars", ["text"] = "Binds when equipped\nHeld In Off-hand\n+ 14 Hit\nRequires Level 40\nUse: Restores 458 mana. (2 Min Cooldown)\nSell Price:" }
entries[43662] = { ["name"] = "Axe of the Plunderer", ["text"] = "Quest Item\nUnique\n\"You would expect this axe to be exceptionally sharp. It's not. The vrykul must have been relying upon his immense strength to hew through his foes.\"" }
entries[43663] = { ["name"] = "Stormbound Tome", ["text"] = "Binds when equipped\nHeld In Off-hand\n+15 Stamina\n+10 Intellect\n+ 9 Critical Strike\nRequires Level 50\nUse: Shocks an enemy for 537 Nature damage. (2 Min Cooldown)\nSell Price:" }
entries[43664] = { ["name"] = "Manual of Clouds", ["text"] = "Binds when equipped\nHeld In Off-hand\n+14 Stamina\n+10 Intellect\n+9 Spirit\nRequires Level 50\nUse: Increases your Spirit by 66 for 1 min. (5 Min Cooldown)\nSell Price:" }
entries[43665] = { ["name"] = "Keristrasza's Broken Heart", ["text"] = "Quest Item\nUnique\n\"A tragic end to a sad tale. If only Malygos's abuse of Keristrasza hadn't driven her insane.\"" }
entries[43666] = { ["name"] = "Hellfire Tome", ["text"] = "Binds when equipped\nHeld In Off-hand\n+28 Intellect\n+20 Fire Resistance\nRequires Level 60\nSell Price:" }
entries[43667] = { ["name"] = "Book of Clever Tricks", ["text"] = "Binds when equipped\nHeld In Off-hand\n+36 Stamina\n+ 15 Hit\n+ 9 Critical Strike\nRequires Level 60\nUse: Increases your dodge by 249 for 15 sec. (5 Min Cooldown)\nSell Price:" }
entries[43668] = { ["name"] = "Ley Line Tuner", ["text"] = "Quest Item\nUnique\n\"You're not quite sure what to make of it. It definitely seethes with arcane magic, but how can something so small be so important?\"" }
entries[43669] = { ["name"] = "Locket of the Deceased Queen", ["text"] = "Quest Item\nUnique\n\"The only reminder that King Ymiron had of his love, Queen Angerboda.\"" }
entries[43670] = { ["name"] = "Prophet's Enchanted Tiki", ["text"] = "Quest Item\nUnique\n\"It seems to have lost all of its mojo with the demise of its bearer.\"" }
entries[43671] = { ["name"] = "Glyph of Path of Frost", ["text"] = "Minor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Path of Frost ability allows you to fall from a greater distance without suffering damage.\nSell Price:" }
entries[43672] = { ["name"] = "Glyph of Resilient Grip", ["text"] = "Minor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen your Death Grip ability fails because its target is immune, its cooldown is reset.\nSell Price:" }
entries[43673] = { ["name"] = "Glyph of Death Gate", ["text"] = "Minor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the cast time of your Death Gate spell by 60%.\nSell Price:" }
entries[43674] = { ["name"] = "Glyph of Dash", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of your Dash ability by 60 sec.\nSell Price:" }
entries[43675] = { ["name"] = "Fandral Staghelm's Silver Coin", ["text"] = "\"The War of the Shifting Sands... I wish I could forget it ever happened.\"\nSell Price:" }
entries[43676] = { ["name"] = "Arcanist Doan's Silver Coin", ["text"] = "\"Oh, why won't you notice me? Abbendis, I would follow you anywhere. I wish you would notice me...\"\nSell Price:" }
entries[43677] = { ["name"] = "High Tinker Mekkatorque's Silver Coin", ["text"] = "\"How does this fountain even work? I wonder if I could make one.\"\nSell Price:" }
entries[43678] = { ["name"] = "Antonidas' Silver Coin", ["text"] = "\"Grant me the strength to accept the things that I cannot change, the courage to change the things I can and the wisdom to know the difference.\"\nSell Price:" }
entries[43679] = { ["name"] = "Muradin Bronzebeard's Silver Coin", ["text"] = "\"May the Holy Light protect us on our expedition to the frozen north.\"\nSell Price:" }
entries[43680] = { ["name"] = "King Varian Wrynn's Silver Coin", ["text"] = "\"I wish the uprising back at home would settle itself soon. I wouldn't want anyone to be hurt.\"\nSell Price:" }
entries[43681] = { ["name"] = "King Terenas Menethil's Silver Coin", ["text"] = "\"May my son Arthas always act in the best interest of his people.\"\nSell Price:" }
entries[43682] = { ["name"] = "King Anasterian Sunstrider's Silver Coin", ["text"] = "\"I hope young Kael'thas realizes that one day he must lead our people.\"\nSell Price:" }
entries[43683] = { ["name"] = "Khadgar's Silver Coin", ["text"] = "\"Turalyon and Alleria, wherever you are, may you be well.\"\nSell Price:" }
entries[43684] = { ["name"] = "Medivh's Silver Coin", ["text"] = "\" \"\nSell Price:" }
entries[43685] = { ["name"] = "Maiev Shadowsong's Silver Coin", ["text"] = "\"Where's Illidan?\"\nSell Price:" }
entries[43686] = { ["name"] = "Alleria's Silver Coin", ["text"] = "\"May my sisters realize their full potential, the name Windrunner known as result of their deeds.\"\nSell Price:" }
entries[43687] = { ["name"] = "Aegwynn's Silver Coin", ["text"] = "\"I really wish you mages would get your heads out from inside your own... books.\"\nSell Price:" }
entries[43688] = { ["name"] = "Weeping Quarry Document", ["text"] = "Quest Item" }
entries[43689] = { ["name"] = "Weeping Quarry Ledger", ["text"] = "Quest Item" }
entries[43690] = { ["name"] = "Weeping Quarry Schedule", ["text"] = "Quest Item" }
entries[43691] = { ["name"] = "Weeping Quarry Map", ["text"] = "Quest Item" }
entries[43693] = { ["name"] = "Mojo Remnant of Akali", ["text"] = "Quest Item\nUnique\n\"Hard to believe that this is all that is left of the once mighty rhino god.\"" }
entries[43694] = { ["name"] = "Drowned Rat", ["text"] = "\"Looks like falling in the soup pot did not work out so well this time.\"\nSell Price:" }
entries[43695] = { ["name"] = "Half Full Bottle of Prison Moonshine", ["text"] = "Use: A strong alcoholic beverage.\n\"Also useful for removing paint.\"\nSell Price:" }
entries[43696] = { ["name"] = "Half Empty Bottle of Prison Moonshine", ["text"] = "Use: A strong alcoholic beverage.\n\"Also useful for removing paint.\"\nSell Price:" }
entries[43697] = { ["name"] = "Artifact from the Nathrezim Homeworld", ["text"] = "Quest Item\nUnique\n\"What strange construction. It must be one of the most alien-looking objects you've ever seen.\"" }
entries[43698] = { ["name"] = "Giant Sewer Rat", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss a Giant Sewer Rat\nSell Price:" }
entries[43699] = { ["name"] = "The Curse of Flesh Disc", ["text"] = "Quest Item\nUnique\n\"There's information on this thing? What? There's no writing!\"" }
entries[43701] = { ["name"] = "A Footman's Copper Coin", ["text"] = "\"Wish I had that cousin of mine's duty to do nothing more than lug wood around carelessly...\"\nSell Price:" }
entries[43702] = { ["name"] = "Alonsus Faol's Copper Coin", ["text"] = "\"One day, I hope to spread the path of the Light to the common people and teach them the value of the Three Virtues.\"\nSell Price:" }
entries[43703] = { ["name"] = "Ansirem's Copper Coin", ["text"] = "\"I wish for happiness and acceptance for my daughter. She feels so out of place here...\"\nSell Price:" }
entries[43704] = { ["name"] = "Attumen's Copper Coin", ["text"] = "\"Can I have a more comfortable saddle? My hindquarters ache.\"\nSell Price:" }
entries[43705] = { ["name"] = "Danath's Copper Coin", ["text"] = "\"I hope a troll dies, right... NOW.\"\nSell Price:" }
entries[43706] = { ["name"] = "Dornaa's Shiny Copper Coin", ["text"] = "\"I wish that that jerk Arthas would fall into a pile of magnataur doody!\"\nSell Price:" }
entries[43707] = { ["name"] = "Eitrigg's Copper Coin", ["text"] = "\"May Tirion's quest here in Northrend end with success, or may he die honorably in battle.\"\nSell Price:" }
entries[43708] = { ["name"] = "Elling Trias' Copper Coin", ["text"] = "\"Being a rogue is hard work. Someday I hope to pursue my life's one true passion...\"\nSell Price:" }
entries[43709] = { ["name"] = "Falstad Wildhammer's Copper Coin", ["text"] = "\"I hope I end up in another book eventually.\"\nSell Price:" }
entries[43710] = { ["name"] = "Genn's Copper Coin", ["text"] = "\"Pah, the fountains in Gilneas could grant ten times as many wishes as Dalaran's!\"\nSell Price:" }
entries[43711] = { ["name"] = "Inigo's Copper Coin", ["text"] = "\"I wish I had my father back...\"\nSell Price:" }
entries[43712] = { ["name"] = "Krasus' Copper Coin", ["text"] = "\"My prayers go out to my brothers and sisters who still suffer in the heart of Grim Batol. I WILL free them.\"\nSell Price:" }
entries[43713] = { ["name"] = "Kryll's Copper Coin", ["text"] = "\"Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it'll explode.\"\nSell Price:" }
entries[43714] = { ["name"] = "Landro Longshot's Copper Coin", ["text"] = "\"I wish I'd kept that coin...\"\nSell Price:" }
entries[43715] = { ["name"] = "Molok's Copper Coin", ["text"] = "\"Just once -- that's all I ask for, just once -- let the lass ride with me...\"\nSell Price:" }
entries[43716] = { ["name"] = "Murky's Copper Coin", ["text"] = "\"I wish the water in Northrend wasn't so cold, it makes me sleepy.\"\nSell Price:" }
entries[43717] = { ["name"] = "Princess Calia Menethil's Copper Coin", ["text"] = "\"I hope that handsome nobleman Lord Prestor notices me! He's so dreamy!\"\nSell Price:" }
entries[43718] = { ["name"] = "Private Marcus Jonathan's Copper Coin", ["text"] = "\"I wish to grow a glorious, bushy mustache someday.\"\nSell Price:" }
entries[43719] = { ["name"] = "Salandria's Shiny Copper Coin", ["text"] = "\"Someday, I'm gonna be more powerful than all of these mages!\"\nSell Price:" }
entries[43720] = { ["name"] = "Squire Rowe's Copper Coin", ["text"] = "\"I hope I can get transferred out of Stormwind eventually and see Cersei again. Nothing good ever happens in this city.\"\nSell Price:" }
entries[43721] = { ["name"] = "Stalvan's Copper Coin", ["text"] = "\"You mages refuse to provide me that which hastens the inevitable fate of two people in love, when only one is too naive to see it. I wish you all ruin.\"\nSell Price:" }
entries[43722] = { ["name"] = "Vereesa's Copper Coin", ["text"] = "\"Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...\"\nSell Price:" }
entries[43723] = { ["name"] = "Vargoth's Copper Coin", ["text"] = "\"I wish Captain Sanders would hurry up with my shipment of wine.\"\nSell Price:" }
entries[43724] = { ["name"] = "Celestial Ruby Ring", ["text"] = "Quest Item\nUnique\n\"Ring? It's more like a necklace and a heavy one at that!\"" }
entries[43725] = { ["name"] = "Glyph of Ghost Wolf", ["text"] = "Major Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile in Ghost Wolf form, you are less hindered by effects that would reduce movement speed.\nSell Price:" }
entries[43726] = { ["name"] = "The Idle Crown of Anub'arak", ["text"] = "Quest Item\nUnique\n\"The crypt lord still carried it though he lost his royal title long ago when he entered the service of the Lich King.\"" }
